package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	exhibit, _ := reader.ReadString('\n')
	exhibit = strings.TrimRight(exhibit, "\r\n")

	arr := []rune{'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'}

	count := 0
	currentIndex := 0

	for _, char := range exhibit {
		index := -1
		for i, l := range arr {
			if l == char {
				index = i
				break
			}
		}

		distanceIndex := index - currentIndex
		if distanceIndex < 0 {
			distanceIndex = -distanceIndex
		}

		if distanceIndex > 13 {
			if index < currentIndex {
				count += index + 26 - currentIndex
			} else {
				count += currentIndex + 26 - index
			}
		} else {
			count += distanceIndex
		}
		currentIndex = index
	}

	fmt.Println(count)
}

